// Spanish help for the effects and shapes, keyed by their English description (engine descriptions.ts).
// When an English description changes, its old entry stops matching and the English shows until it is updated:
// the i18n test lists those.
export const ES_EFFECTS: Record<string, string> = {
  // transform
  'Moves, rotates and scales the whole drawing, around a pivot. Offsets are in drawing units (px).':
    'Mueve, gira y escala todo el dibujo alrededor de un pivote. Los desplazamientos van en unidades del dibujo (px).',
  // rotate3d
  'Moves and rotates the drawing in 3D around a pivot, then projects it onto 2D with perspective. Positive Translate Z moves it toward the viewer and makes it appear larger; negative values move it farther away. X/Y tilt and Z spins the drawing.':
    'Mueve y gira el dibujo en 3D alrededor de un pivote y luego lo proyecta en 2D con perspectiva. Un Translate Z positivo lo acerca al espectador y lo hace parecer más grande; los valores negativos lo alejan. X/Y lo inclinan y Z lo hace girar.',
  // spherize
  'Bulges (strength > 0) or pinches (strength < 0) what falls inside a circle. The edge of the circle does not move, so there is no jump with what is outside. After Rigid Pieces, each marked element moves and turns as a plate instead of bending.':
    'Abomba (strength > 0) o pellizca (strength < 0) lo que cae dentro de un círculo. El borde del círculo no se mueve, así que no hay salto con lo de fuera. Después de Rigid Pieces, cada elemento marcado se mueve y gira como una placa en vez de doblarse.',
  // rigidpieces
  'Marks each current element as a rigid piece. Amount blends normal pointwise deformation with whole-piece motion: 0 bends normally, 1 preserves the piece shape. Nested Transform and Transform 3D wait until a downstream deformer actually moves the piece. Transform 3D also moves each piece along camera Z, projecting that depth into scale. Nest Color, Tint, Opacity, Paint, Gradient or Feather to style pieces individually; Pivot sets the shared rotation anchor.':
    'Marca cada elemento actual como una pieza rígida. Amount mezcla la deformación normal punto a punto con el movimiento de la pieza entera: 0 dobla con normalidad, 1 conserva la forma de la pieza. Transform y Transform 3D anidados esperan a que un deformador posterior mueva de verdad la pieza. Transform 3D también mueve cada pieza en el eje Z de la cámara y convierte esa profundidad en escala. Anida Color, Tint, Opacity, Paint, Gradient o Feather para dar estilo a cada pieza; Pivot fija el ancla de giro común.',
  // twist
  'A whirl: turns more the closer a point is to the center, and nothing at the edge of the radius.':
    'Un remolino: gira más cuanto más cerca del centro está un punto, y nada en el borde del radio.',
  // bend
  'Curves the drawing like a sheet: the chosen axis becomes an arc of `angle` degrees. Positive angles bend the ends down (∩), negative ones up (∪).':
    'Curva el dibujo como una lámina: el eje elegido se convierte en un arco de `angle` grados. Los ángulos positivos doblan los extremos hacia abajo (∩) y los negativos hacia arriba (∪).',
  // bones
  'A chain of 2 to 6 bones from Start to End, each with its own length (relative to the others). Each bone turns on its joint (relative to the previous one) and drags what is around it; at each joint the drawing bends round an arc, keeping its thickness, and Smooth sets how long that arc is. With a Target, the angles are solved (IK) so the tip reaches it.':
    'Una cadena de 2 a 6 huesos de Start a End, cada uno con su longitud (relativa a los demás). Cada hueso gira sobre su articulación (respecto al anterior) y arrastra lo que tiene alrededor; en cada articulación el dibujo se dobla en un arco sin perder grosor, y Smooth fija lo largo que es ese arco. Con un Target, los ángulos se calculan (IK) para que la punta llegue a él.',
  // gather
  'Squeezes the drawing towards one side along an axis, by an amount that changes across it: Start applies at one edge (top for axis x, left for axis y), End at the other, positive towards the left/top and negative towards the right/bottom. Straight lines across the axis stay straight, so a row of bars becomes a fan whose spacing drifts (weaves, moiré, fake perspective). Strokes keep their width.':
    'Aprieta el dibujo hacia un lado a lo largo de un eje, con una cantidad que cambia a lo ancho: Start se aplica en un borde (arriba con el eje x, a la izquierda con el eje y) y End en el otro; positivo hacia la izquierda/arriba y negativo hacia la derecha/abajo. Las líneas rectas que cruzan el eje siguen rectas, así que una fila de barras se convierte en un abanico de separación variable (tramas, moiré, falsa perspectiva). Los trazos mantienen su grosor.',
  // compress
  'Crowds the drawing towards a center line along one axis (Strength > 0) or spreads it away from it (Strength < 0); both ends of the box stay put and the order of points is kept. The center goes from Start at one edge (top for axis x, left for axis y) to End at the other (fractions across the axis). With Rigid Pieces first, evenly spaced marks keep their shape and pile into a solid bar at the center, so a Clone grid gets a dense band that can sweep diagonally row by row.':
    'Apiña el dibujo hacia una línea central a lo largo de un eje (Strength > 0) o lo separa de ella (Strength < 0); los dos extremos de la caja se quedan quietos y se mantiene el orden de los puntos. El centro va de Start en un borde (arriba con el eje x, a la izquierda con el eje y) a End en el otro (fracciones a lo ancho del eje). Con Rigid Pieces antes, unas marcas equiespaciadas mantienen su forma y se amontonan en una barra sólida en el centro, así una rejilla de Clone forma una banda densa que puede barrer en diagonal fila a fila.',
  // rope
  'Open paths hang as ropes pinned at both ends: a Verlet chain with the drawn length, Gravity, Wind and Damping, that settles and swings. Pointer and Radius place a round obstacle that pushes the ropes out of its way (bind Pointer to the cursor with `scene.mouse` formulas, Space set to Scene). Time follows scene.time unless it is set; keep Rope first in the stack, as it keeps its state between frames. Closed paths are left alone.':
    'Los trazados abiertos cuelgan como cuerdas sujetas por los dos extremos: una cadena de Verlet con la longitud dibujada, Gravity, Wind y Damping, que se asienta y se balancea. Pointer y Radius colocan un obstáculo redondo que aparta las cuerdas (vincula Pointer al cursor con fórmulas `scene.mouse` y Space en Scene). Time sigue a scene.time salvo que se fije; deja Rope el primero de la pila, porque guarda su estado entre fotogramas. Los trazados cerrados no se tocan.',
  // taper
  'Narrows (or widens) one end: the width across the axis changes along it.':
    'Estrecha (o ensancha) un extremo: el ancho a través del eje cambia a lo largo de él.',
  // shear
  'Slants the drawing: X shifts with the height and Y with the width, around the center.':
    'Inclina el dibujo: X se desplaza con la altura e Y con el ancho, alrededor del centro.',
  // wave
  'Makes the drawing wavy: moves each point across the direction of the wave.':
    'Ondula el dibujo: mueve cada punto en perpendicular a la dirección de la onda.',
  // ripple
  'Concentric waves from a point, like a drop in water; they fade with the distance.':
    'Ondas concéntricas desde un punto, como una gota en el agua; se desvanecen con la distancia.',
  // noise
  'Moves each point with smooth noise: an organic, hand-drawn look.':
    'Mueve cada punto con un ruido suave: un aspecto orgánico, como dibujado a mano.',
  // roughen
  'Fractal edges on any drawing: `organic` tears the outline (midpoint displacement, like a coastline or torn paper); `koch` turns each segment into a Koch peak, `iterations` times. Curves become straight segments.':
    'Bordes fractales en cualquier dibujo: `organic` rasga el contorno (desplazamiento del punto medio, como una costa o un papel rasgado); `koch` convierte cada segmento en un pico de Koch, `iterations` veces. Las curvas pasan a ser segmentos rectos.',
  // blob
  'Turns every outline into a blob: a smooth closed curve with no straight sides or corners. Inset first pulls the outline inwards (px; negative grows it), which on touching cells such as Voronoi or Mosaic opens the gaps between them; a cell smaller than the inset disappears. Roundness sets how much of each side the corners take: 0 keeps the polygon, 1 is a tangent-continuous curve through the middle of every side. Curved input is sampled first, so circles stay round and straight sides keep their real corners. Open paths keep their ends. Stack Noise or Displace after it for an irregular, organic edge.':
    'Convierte cada contorno en una mancha: una curva cerrada suave, sin lados rectos ni esquinas. Inset primero mete el contorno hacia dentro (px; en negativo lo agranda), lo que en celdas que se tocan, como Voronoi o Mosaic, abre huecos entre ellas; una celda más pequeña que el inset desaparece. Roundness fija cuánto de cada lado ocupan las esquinas: 0 mantiene el polígono y 1 es una curva continua en tangente que pasa por el centro de cada lado. Las curvas de entrada se muestrean antes, así los círculos siguen redondos y los lados rectos conservan sus esquinas reales. Los trazados abiertos conservan sus extremos. Pon Noise o Displace después para un borde irregular y orgánico.',
  // roundcorners
  'Rounds the corners: wherever the path changes direction sharply, it cuts both segments and joins them with an arc of `radius` px (or a straight cut, `chamfer`). A corner radius is capped at half the length of either adjoining side. Smooth curves are left alone; `limit` keeps corners wider than that angle. Set Corners to Random to choose a stable seeded subset independently for each clone.':
    'Redondea las esquinas: donde el trazado cambia de dirección bruscamente, corta los dos segmentos y los une con un arco de `radius` px (o con un corte recto, `chamfer`). El radio de una esquina se limita a la mitad de la longitud de cualquiera de sus lados. Las curvas suaves no se tocan; `limit` deja las esquinas más abiertas que ese ángulo. Pon Corners en Random para elegir, en cada copia de Clone, un subconjunto estable con semilla.',
  // spikes
  'Regular spikes along the outline: `count` tips per path, evenly spaced, `height` px out (negative: inwards). `curve` shapes the sides: 0 straight, towards 1 hollow like thorns, towards -1 bulging like petals. `width` leaves outline between spikes, `lean` tilts the tips and `phase` slides them along.':
    'Púas regulares a lo largo del contorno: `count` puntas por trazado, equiespaciadas, a `height` px hacia fuera (en negativo, hacia dentro). `curve` da forma a los lados: 0 rectos, hacia 1 cóncavos como espinas, hacia -1 abombados como pétalos. `width` deja contorno entre púas, `lean` inclina las puntas y `phase` las desliza.',
  // melt
  'The drawing drips downwards, more the lower it is; noise decides where the drops fall.':
    'El dibujo gotea hacia abajo, más cuanto más abajo está; el ruido decide dónde caen las gotas.',
  // cylinder
  'Wraps the drawing around a vertical cylinder (like the label of a can). `wrap` is the part of the turn the drawing covers; the sides compress and move closer or away.':
    'Envuelve el dibujo en un cilindro vertical (como la etiqueta de una lata). `wrap` es la parte de la vuelta que cubre el dibujo; los lados se comprimen y se acercan o se alejan.',
  // perspective
  'Free perspective: each corner of the drawing goes where you drag its handle.':
    'Perspectiva libre: cada esquina del dibujo va adonde arrastres su tirador.',
  // envelope
  'Envelope distortion: drag the nine points of the mesh and the drawing bends with it.':
    'Distorsión por envolvente: arrastra los nueve puntos de la malla y el dibujo se dobla con ella.',
  // pathwrap
  'Wraps the drawing along another object\'s path (its longest one). The drawing\'s axis follows the path; what is across it moves away from it. `stretch` fills the whole path; `keep` keeps its length and starts at `offset`.':
    'Envuelve el dibujo a lo largo del trazado de otro objeto (el más largo). El eje del dibujo sigue el trazado; lo que lo cruza se aleja de él. `stretch` ocupa todo el trazado; `keep` mantiene su longitud y empieza en `offset`.',
  // morph
  'Morphs this drawing into another object\'s shape. Paths are paired (largest with largest), resampled to the same number of points and interpolated; extra paths grow from (or shrink to) a point. Fill and stroke blend too. With `steps`, the in-between shapes as separate elements.':
    'Transforma este dibujo en la forma de otro objeto. Los trazados se emparejan (el más grande con el más grande), se remuestrean al mismo número de puntos y se interpolan; los trazados que sobran crecen desde un punto (o menguan hasta él). El relleno y el contorno también se mezclan. Con `steps`, las formas intermedias como elementos separados.',
  // trim
  'Trims paths (draws them): only the part of each path between Start and End (fractions of its length) remains, shifted by Offset; closed paths wrap around. Animate End from 0 to 1 and the stroke draws itself.':
    'Recorta los trazados (los dibuja): de cada trazado solo queda la parte entre Start y End (fracciones de su longitud), desplazada por Offset; los trazados cerrados dan la vuelta. Anima End de 0 a 1 y el trazo se dibuja solo.',
  // followpath
  'Moves the whole object, without bending it, to a point on another object\'s path: `position` is the fraction of the way (0 start, 1 end; closed paths loop). `anchor` is the point of the object that sits on the path; `orient` turns it with the path.':
    'Mueve el objeto entero, sin doblarlo, a un punto del trazado de otro objeto: `position` es la fracción del recorrido (0 inicio, 1 final; los trazados cerrados dan la vuelta). `anchor` es el punto del objeto que se apoya en el trazado; `orient` lo gira con el trazado.',
  // lookat
  'Turns the object so that it faces another one (its center), around `pivot`. `facing` says which side is the front (0 right, -90 up, 90 down, 180 left); `amount`, how much it turns. If the other moves, it keeps looking.':
    'Gira el objeto para que mire a otro (a su centro), alrededor de `pivot`. `facing` indica qué lado es el frente (0 derecha, -90 arriba, 90 abajo, 180 izquierda); `amount`, cuánto gira. Si el otro se mueve, lo sigue mirando.',
  // connect
  'Joins two objects with a line that follows them: the drawing becomes the stretch from `from` to `to` (their anchors, fractions of their box), keeping its style. Straight, arc, horizontal or vertical; from edge to edge with a `gap`; optional arrowheads. Utils → Connector creates it.':
    'Une dos objetos con una línea que los sigue: el dibujo se convierte en el tramo de `from` a `to` (sus anclas, fracciones de su caja), con su estilo. Recta, en arco, horizontal o vertical; de borde a borde con un `gap`; con puntas de flecha opcionales. Utils → Connector lo crea.',
  // network
  'Draws elastic links between each shape and its nearest neighbours while leaving the source shapes in place. Links stay attached under Explosion, Gravity and Physics, sag with slack, and break when stretched past their resistance. Neighbour count, distance and link width are adjustable; links inherit the source colour, which Color or Tint can change after Network.':
    'Dibuja enlaces elásticos entre cada forma y sus vecinas más cercanas, sin mover las formas de origen. Los enlaces siguen unidos con Explosion, Gravity y Physics, se comban con holgura y se rompen si se estiran más allá de su resistencia. Se ajustan el número de vecinas, la distancia y el grosor del enlace; los enlaces heredan el color de origen, que Color o Tint pueden cambiar después de Network.',
  // weave
  'At every crossing between open stroked paths, alternates which path passes over and cuts a small gap into the path underneath. Use it on linework such as two cloned grids; it keeps the source elements editable.':
    'En cada cruce entre trazados abiertos con contorno, alterna cuál pasa por encima y abre un pequeño hueco en el de debajo. Úsalo en dibujos de líneas, como dos rejillas clonadas; los elementos de origen siguen siendo editables.',
  // stringart
  'Samples evenly spaced points around each closed contour and connects each point to another a fixed number of steps ahead, drawing a modular chord pattern as editable vector lines. Points controls the sampling resolution, Skip changes the star pattern and Phase shifts where sampling begins.':
    'Toma puntos equiespaciados alrededor de cada contorno cerrado y une cada punto con otro un número fijo de pasos más adelante, dibujando un patrón modular de cuerdas como líneas vectoriales editables. Points controla la resolución del muestreo, Skip cambia el patrón de estrella y Phase desplaza dónde empieza el muestreo.',
  // spirograph
  'Draws a closed rolling-gear curve inside the input bounds. Hypo rolls a wheel inside a ring; Epi rolls it outside. Ring teeth and Wheel teeth determine the gear ratio, Pen offset moves the drawing point away from the wheel centre, and Detail controls curve resolution.':
    'Dibuja una curva cerrada de engranajes dentro de los límites de la entrada. Hypo hace rodar una rueda dentro de un anillo; Epi, por fuera. Ring teeth y Wheel teeth fijan la relación de engranaje, Pen offset aleja el punto de dibujo del centro de la rueda y Detail controla la resolución de la curva.',
  // flowfield
  'Seeds smooth vector streamlines inside the input silhouette and integrates them through a deterministic noise-driven direction field. Lines stops the field work at a bounded count; Length, Step, Field scale, Curl and Direction shape the paths, and Seed reproduces the same flow.':
    'Siembra líneas de flujo vectoriales suaves dentro de la silueta de la entrada y las integra a través de un campo de direcciones determinista guiado por ruido. Lines limita el trabajo del campo a un número de líneas; Length, Step, Field scale, Curl y Direction dan forma a los recorridos, y Seed reproduce el mismo flujo.',
  // wavelines
  'Turns sampled tone into horizontal vector lines. Darkness shapes each line’s offset and weight; Line spacing, Sample spacing, Wave amount and Wavelength control the texture. Speed moves the wave over Time, which follows scene.time unless it is set. Lines stay within the sampled silhouette; use Color or Tint after Wave Lines to style them.':
    'Convierte el tono muestreado en líneas vectoriales horizontales. La oscuridad da forma al desplazamiento y al grosor de cada línea; Line spacing, Sample spacing, Wave amount y Wavelength controlan la textura. Speed mueve la onda con Time, que sigue a scene.time salvo que se fije. Las líneas se quedan dentro de la silueta muestreada; usa Color o Tint después de Wave Lines para darles estilo.',
  // trace
  'A trail: the drawing becomes the path another object\'s center followed during the last `length` seconds of the animation, keeping its style. Shown while playing or scrubbing. Utils → Tracer creates it.':
    'Una estela: el dibujo se convierte en el recorrido que siguió el centro de otro objeto durante los últimos `length` segundos de la animación, con su estilo. Se ve al reproducir o al mover el cabezal. Utils → Tracer lo crea.',
  // crack
  'Fractures filled shapes with either branching cracks from an impact or edge-to-edge slices. In Impact pattern, Spread controls where side branches form: lower values strongly concentrate them near the impact without reducing their expected count; 1 distributes them evenly along the cracks. `cut` cuts lines as gaps of `width` px; `shatter` cuts them into elements and pushes the loose pieces apart. Separation sets the distance and Variation controls how much that distance differs between pieces, deterministically from the seed.':
    'Fractura formas rellenas con grietas ramificadas desde un impacto o con cortes de borde a borde. En el patrón Impact, Spread controla dónde salen las ramas laterales: los valores bajos las concentran mucho cerca del impacto sin reducir su número esperado; 1 las reparte por igual a lo largo de las grietas. `cut` corta las líneas como huecos de `width` px; `shatter` las corta en elementos y separa las piezas sueltas. Separation fija la distancia y Variation cuánto cambia entre piezas, de forma determinista a partir de la semilla.',
  // radialcut
  'Cuts filled shapes into radial sectors like slices of a cake. Count controls the number of pieces. Offset rotates the whole cut. Spin progressively rotates each sector around its own centre to create a pinwheel or spiral. Drag Center to move the pivot. Separation pulls each sector outward from that point.':
    'Corta formas rellenas en sectores radiales, como porciones de una tarta. Count controla el número de piezas. Offset gira todo el corte. Spin gira progresivamente cada sector alrededor de su propio centro para crear un molinillo o una espiral. Arrastra Center para mover el pivote. Separation aleja cada sector de ese punto.',
  // damage
  'Wear: cracks coming in from the edges, chips on the edge and specks, cut as holes. Everything comes from a seed; `growth` makes the cracks advance. Surfaces only.':
    'Desgaste: grietas que entran desde los bordes, desconchones en el borde y motas, cortados como agujeros. Todo sale de una semilla; `growth` hace avanzar las grietas. Solo en superficies.',
  // clone
  'Duplicates the drawing in a grid, concentric rings or a line, around the original. Grid can pack 2×2 large copies by reserving their cells, so the copies do not overlap; Gap sets the clear space between cells, Big / normal sets their share and Seed shuffles their placement. In Radial, Count copies are placed on each of Rings circles; Ring spacing controls the distance between radii. In `object` mode, on another object: along its outline, on its vertices or inside it (random, with a seed). Each copy is an element. Fill keeps a share of the grid cells (a 2×2 copy counts as four): at random with Fill direction 0, or growing from the side Fill angle points to (90° is the bottom) towards 1, with a ragged edge; Fill seed varies it.':
    'Duplica el dibujo en una rejilla, en anillos concéntricos o en una línea, alrededor del original. La rejilla puede encajar copias grandes de 2×2 reservando sus celdas, para que las copias no se solapen; Gap fija el espacio libre entre celdas, Big / normal su proporción y Seed baraja su colocación. En Radial, se colocan Count copias en cada uno de los Rings círculos; Ring spacing controla la distancia entre radios. En modo `object`, sobre otro objeto: a lo largo de su contorno, en sus vértices o dentro de él (al azar, con semilla). Cada copia es un elemento. Fill conserva una parte de las celdas de la rejilla (una copia de 2×2 cuenta como cuatro): al azar con Fill direction 0, o creciendo desde el lado al que apunta Fill angle (90° es abajo) hacia 1, con un borde irregular; Fill seed lo varía.',
  // mirror
  'Reflects the drawing on an axis at a fraction of its box. `keep` keeps the original and adds the reflection (symmetry); `transform` replaces it with its reflection. Reference optionally measures another node (even hidden), allowing a fixed axis for generated collections.':
    'Refleja el dibujo en un eje situado en una fracción de su caja. `keep` mantiene el original y añade el reflejo (simetría); `transform` lo sustituye por su reflejo. Reference puede medir otro nodo (aunque esté oculto), lo que permite un eje fijo para colecciones generadas.',
  // mosaic
  'Cuts the drawing into tiles on a grid of columns × rows, with a gutter and a rotated grid: rectangles, triangles, hexagons, or one shape per cell (circle, polygon, star or another object). `cut` clips the drawing with each tile; `whole` places whole tiles where the drawing covers at least half.':
    'Corta el dibujo en teselas sobre una rejilla de columnas × filas, con calle y rejilla girada: rectángulos, triángulos, hexágonos o una forma por celda (círculo, polígono, estrella u otro objeto). `cut` recorta el dibujo con cada tesela; `whole` pone teselas enteras donde el dibujo cubre al menos la mitad.',
  // voronoi
  'Turns filled artwork into jittered Voronoi cells, clipped to its silhouette. Cell size controls density; Jitter and Seed shape the tessellation. Gap (2 px by default) leaves an even space between neighbouring cells, so they read even on a flat fill; set it to 0 for a closed tessellation. Cells sample and preserve source colour; use Color or Tint after Voronoi to style them. Optional Drift moves the sites smoothly and recomputes all cells together, keeping their shared borders aligned. Cells remain separate elements for effects such as Step, Color and Physics. Large grids coarsen automatically above about 1,000 sites.':
    'Convierte el dibujo relleno en celdas de Voronoi con variación, recortadas a su silueta. Cell size controla la densidad; Jitter y Seed dan forma a la teselación. Gap (2 px por defecto) deja un espacio uniforme entre celdas vecinas, para que se distingan incluso con un relleno plano; ponlo a 0 para una teselación cerrada. Las celdas toman y conservan el color de origen; usa Color o Tint después de Voronoi para darles estilo. Drift, opcional, mueve los centros con suavidad y recalcula todas las celdas a la vez, manteniendo alineados sus bordes comunes. Las celdas siguen siendo elementos separados para efectos como Step, Color y Physics. Las rejillas grandes se simplifican solas por encima de unos 1.000 centros.',
  // fractal
  'Repeats the drawing inside itself, smaller each time (an iterated function system): Sierpinski triangle, Sierpinski carpet, a branching tree or a spiral. Capped at 4,096 copies.':
    'Repite el dibujo dentro de sí mismo, cada vez más pequeño (un sistema de funciones iteradas): triángulo de Sierpinski, alfombra de Sierpinski, un árbol ramificado o una espiral. Hasta 4.096 copias.',
  // vectorgrain
  'Vector stipple that gathers at the edges, as real marks (not the SVG Grain filter). Density is highest at the edge and falls off over Falloff px, shaped by Curve, down to Interior deep inside. Edge: inside the shape, outside (a halo) or both. Marks are circles, squares or irregular specks; Size, Size jitter and Edge size control them. Their base colour comes from the source fill; use Color or Tint after Vector Grain to style the output. Opacity and Opacity jitter vary mark opacity, Distribution is random or even, and Source keeps or replaces the drawing. Seeded.':
    'Punteado vectorial que se concentra en los bordes, como marcas reales (no el filtro Grain de SVG). La densidad es máxima en el borde y cae a lo largo de Falloff px, con la forma de Curve, hasta Interior en lo más profundo. Edge: dentro de la forma, fuera (un halo) o ambos. Las marcas son círculos, cuadrados o motas irregulares; Size, Size jitter y Edge size las controlan. Su color base sale del relleno de origen; usa Color o Tint después de Vector Grain para dar estilo al resultado. Opacity y Opacity jitter varían la opacidad de las marcas, Distribution es aleatoria o uniforme y Source conserva o sustituye el dibujo. Con semilla.',
  // halftone
  'A halftone screen: the drawing sampled on a rotated grid where each cell becomes a mark (circle, square, diamond, line or ring) sized by the tone. Spacing, angle, min/max size, gamma, invert and jitter control the geometry. Marks retain sampled source colour; use Color or Tint after Halftone to style them.':
    'Una trama de semitono: el dibujo muestreado sobre una rejilla girada en la que cada celda se convierte en una marca (círculo, cuadrado, rombo, línea o anillo) con el tamaño del tono. Spacing, angle, min/max size, gamma, invert y jitter controlan la geometría. Las marcas conservan el color de origen muestreado; usa Color o Tint después de Halftone para darles estilo.',
  // crosshatch
  'Pen-drawing shading with parallel lines: up to four layers of hatching (at Angle, then +90°, +45° and −45°), each drawn only where the tone is darker than its threshold, so dark areas get denser cross-hatching. Spacing, line width, gamma, invert and offset control the look; Fix lines anchors the screen to the scene as the object moves, rotates or scales; off, the lines follow the object. Lines retain sampled source colour; use Color or Tint after Crosshatch to style them. Merge joins lines into one path per sampled source style and keeps the whole drawing as one physics body (Gravity or Physics), on both Solids and the Floor; off, each line is a separate body. Canvas handles adjust Offset, Angle and Spacing. Add Roughen after it for a hand-drawn line.':
    'Sombreado de plumilla con líneas paralelas: hasta cuatro capas de rayado (en Angle, luego +90°, +45° y −45°), cada una dibujada solo donde el tono es más oscuro que su umbral, así las zonas oscuras tienen un tramado más denso. Spacing, line width, gamma, invert y offset controlan el aspecto; Fix lines ancla la trama a la escena mientras el objeto se mueve, gira o escala; desactivado, las líneas siguen al objeto. Las líneas conservan el color de origen muestreado; usa Color o Tint después de Crosshatch para darles estilo. Merge une las líneas en un trazado por cada estilo de origen y mantiene todo el dibujo como un solo cuerpo físico (Gravity o Physics), tanto en Solids como en el Floor; desactivado, cada línea es un cuerpo aparte. Los tiradores del lienzo ajustan Offset, Angle y Spacing. Añade Roughen después para una línea hecha a mano.',
  // dithering
  'Converts sampled tone into a binary grid of vector cells. Bayer uses an ordered 2×2 to 16×16 threshold matrix; Floyd–Steinberg and Atkinson diffuse quantization error for smoother tonal patterns; Noise uses a repeatable seeded random threshold. Cell size, angle, threshold, gamma and invert control the pattern. Cells retain sampled source colour; use Color or Tint after Dithering to style them. Merge combines contiguous cells into larger rectangles and same-colour paths. Large grids increase cell size automatically to keep sampling bounded.':
    'Convierte el tono muestreado en una rejilla binaria de celdas vectoriales. Bayer usa una matriz de umbrales ordenada de 2×2 a 16×16; Floyd–Steinberg y Atkinson difunden el error de cuantización para patrones tonales más suaves; Noise usa un umbral aleatorio repetible con semilla. Cell size, angle, threshold, gamma e invert controlan el patrón. Las celdas conservan el color de origen muestreado; usa Color o Tint después de Dithering para darles estilo. Merge une las celdas contiguas en rectángulos más grandes y trazados del mismo color. Las rejillas grandes aumentan solas el tamaño de celda para limitar el muestreo.',
  // contour
  'Draws vector isolines through equal tones in the input, like elevation lines on a map. Sample spacing controls detail; Levels sets how many tone bands are outlined. Gamma and Invert reshape the tonal map; line width and Merge control the paths. Lines retain sampled source colour; use Color or Tint after Contour to style them. Large grids adapt their spacing to bound work.':
    'Dibuja isolíneas vectoriales por los tonos iguales de la entrada, como las curvas de nivel de un mapa. Sample spacing controla el detalle; Levels fija cuántas bandas de tono se perfilan. Gamma e Invert remodelan el mapa tonal; line width y Merge controlan los trazados. Las líneas conservan el color de origen muestreado; usa Color o Tint después de Contour para darles estilo. Las rejillas grandes adaptan su separación para limitar el trabajo.',
  // slices
  'Glitch: horizontal bands of the drawing shifted sideways, each one an element.':
    'Glitch: bandas horizontales del dibujo desplazadas de lado, cada una un elemento.',
  // blocks
  'Glitch: rectangular blocks cut out and shown displaced, leaving their gap.':
    'Glitch: bloques rectangulares recortados y mostrados desplazados, dejando su hueco.',
  // scanlines
  'Glitch: scan lines across the drawing, clipped to it.':
    'Glitch: líneas de barrido sobre el dibujo, recortadas a él.',
  // streaks
  'Glitch: streaks escaping sideways from the real edge of the shape. With Bite, the band looks shifted: what sticks out on one side is missing on the other.':
    'Glitch: estelas que se escapan de lado desde el borde real de la forma. Con Bite, la banda parece desplazada: lo que sobresale por un lado falta en el otro.',
  // rgbsplit
  'Chromatic separation with two modes: Channels (default) extracts the source RGB plates, shifting red and blue along Angle while green stays in place. Dark backgrounds use Screen; Light uses complementary CMY plates with Multiply. Solid colours, gradients and paint alpha are preserved. Duo keeps the original two-colour copies with Color A/B, Layer, Blend and Original. Nested effects apply only to the shifted plates, including independent filters; in Duo they apply to the two copies.':
    'Separación cromática con dos modos: Channels (por defecto) extrae las planchas RGB de origen y desplaza el rojo y el azul según Angle mientras el verde se queda quieto. En fondos oscuros usa Screen; en claros, planchas CMY complementarias con Multiply. Se conservan los colores sólidos, los degradados y el alfa de la pintura. Duo mantiene las dos copias de color originales con Color A/B, Layer, Blend y Original. Los efectos anidados solo se aplican a las planchas desplazadas, incluidos filtros independientes; en Duo, a las dos copias.',
  // boolean
  'Boolean operations between elements (a group\'s children, a Clone\'s copies…): union, subtract (the front ones cut the back one), intersect or exclude. Curves are approximated with straight segments.':
    'Operaciones booleanas entre elementos (los hijos de un grupo, las copias de un Clone…): unión, resta (los de delante cortan al de atrás), intersección o exclusión. Las curvas se aproximan con segmentos rectos.',
  // metaball
  'The elements melt together through a smooth union of their two nearest distance fields, keeping multiway junctions stable. Reach controls the blend width; negative Grow contracts the result and can separate narrow joins. Quality adds contour detail and is automatically capped to keep field sampling responsive.':
    'Los elementos se funden mediante una unión suave de sus dos campos de distancia más cercanos, manteniendo estables las uniones múltiples. Reach controla el ancho de la fusión; un Grow negativo contrae el resultado y puede separar uniones estrechas. Quality añade detalle al contorno y se limita sola para que el muestreo del campo siga siendo fluido.',
  // pixelate
  'Everything made of little squares, like pixel art: a grid of `size` px where each cell takes the colour of what is on top at its centre (stroke or fill). Runs of the same colour are merged; `gap` and `dot` give an LED-screen look. Vector, sharp at any size.':
    'Todo hecho de cuadraditos, como el pixel art: una rejilla de `size` px en la que cada celda toma el color de lo que hay encima en su centro (contorno o relleno). Las series del mismo color se unen; `gap` y `dot` dan un aspecto de pantalla LED. Vectorial, nítido a cualquier tamaño.',
  // step
  'Incremental effector: applies the modifiers nested in it to each element separately, with their numbers multiplied by the element\'s position. A 10° Twist under Step turns the first copy 10°, the second 20°…':
    'Efector incremental: aplica los modificadores anidados a cada elemento por separado, con sus números multiplicados por la posición del elemento. Un Twist de 10° dentro de Step gira la primera copia 10°, la segunda 20°…',
  // pulse
  'Repeated pulses of nested effects, from neutral to full strength and back. Attack and Decay are fractions of one cycle; any remaining time is rest. If their sum exceeds 1 they are fitted to one cycle. Frequency, amplitude, offset and per-element phase work as in Oscillate. Time follows scene.time unless it is set.':
    'Pulsos repetidos de los efectos anidados, de neutro a toda su fuerza y vuelta. Attack y Decay son fracciones de un ciclo; el tiempo que sobra es reposo. Si suman más de 1, se ajustan a un ciclo. Frequency, amplitude, offset y la fase por elemento funcionan como en Oscillate. Time sigue a scene.time salvo que se fije.',
  // shake
  'A seeded one-shot impact that loses strength and returns exactly to neutral at Duration. Start schedules the hit; Frequency sets its vibration rate and Decay how quickly it settles. Per element adds independent signals and an Element delay. The default Transform child shakes position and rotation; seeking is deterministic.':
    'Un impacto único con semilla que pierde fuerza y vuelve exactamente a neutro en Duration. Start programa el golpe; Frequency fija la velocidad de vibración y Decay lo rápido que se asienta. Per element añade señales independientes y un Element delay. El Transform hijo por defecto sacude la posición y la rotación; mover el cabezal es determinista.',
  // oscillate
  'Periodic modulation of nested effects: sine, triangle, square or saw. Frequency is cycles per second; amplitude and offset control signal strength. Phase and Element phase are degrees. Disable Per element to move the whole object together. Time follows scene.time unless it is set; numeric child parameters move around their neutral values (scale around 1).':
    'Modulación periódica de los efectos anidados: seno, triángulo, cuadrada o diente de sierra. Frequency son ciclos por segundo; amplitude y offset controlan la fuerza de la señal. Phase y Element phase van en grados. Desactiva Per element para mover todo el objeto a la vez. Time sigue a scene.time salvo que se fije; los parámetros numéricos hijos se mueven alrededor de sus valores neutros (la escala alrededor de 1).',
  // wiggle
  'Smooth seeded random modulation of nested effects. Frequency controls the rate of change, amplitude its strength, offset its centre. Per element gives each clone or glyph an independent reproducible signal. Time follows scene.time unless it is set; seeking backwards gives the same result.':
    'Modulación aleatoria suave y con semilla de los efectos anidados. Frequency controla la velocidad de cambio, amplitude su fuerza y offset su centro. Per element da a cada copia o letra una señal independiente y reproducible. Time sigue a scene.time salvo que se fije; ir hacia atrás da el mismo resultado.',
  // each
  'Applies the effects nested in it to every element separately (Clone copies, letters, tiles…), with formulas that read the element: element.index, element.count, element.row and element.column (grid), element.u and element.v (0–1 across the grid), element.distance (0 at the centre of the elements, 1 for the furthest) and element.random (a fixed 0–1 number per element; Random seed varies it). For example, Each › Transform with scale = 1 - element.distance. A Shape inside it rebuilds each copy with other values for the shape\'s own parameters.':
    'Aplica los efectos anidados a cada elemento por separado (copias de Clone, letras, teselas…), con fórmulas que leen el elemento: element.index, element.count, element.row y element.column (rejilla), element.u y element.v (0–1 a lo ancho de la rejilla), element.distance (0 en el centro de los elementos, 1 en el más lejano) y element.random (un número fijo de 0–1 por elemento; Random seed lo varía). Por ejemplo, Each › Transform con scale = 1 - element.distance. Un Shape dentro reconstruye cada copia con otros valores para los parámetros de la forma.',
  // shapevalues
  'Only inside Each, on a shape object after a Clone: rebuilds every copy with other values for the shape\'s own parameters, by name, usually formulas with element.* (Inner = 19 * (1 - element.distance) closes the holes of a donut grid towards the edges). The new copy keeps its place and style.':
    'Solo dentro de Each, en un objeto de forma después de un Clone: reconstruye cada copia con otros valores para los parámetros de la forma, por su nombre, normalmente fórmulas con element.* (Inner = 19 * (1 - element.distance) cierra los agujeros de una rejilla de donuts hacia los bordes). La nueva copia mantiene su sitio y su estilo.',
  // stagger
  'Each element makes its own transition, with its curve, a little after the previous one. Progress (0–1) is the whole animation: animate it with two keys. `in` brings elements in, `out` takes them away.':
    'Cada elemento hace su propia transición, con su curva, un poco después del anterior. Progress (0–1) es toda la animación: anímalo con dos claves. `in` hace entrar los elementos y `out` los hace salir.',
  // range
  'Selects elements, text words/lines or Clone grid rows/columns for nested effects. Select: All, Even, Odd or CSS-style An+B (one-based). Start/End/Offset limit the selection; Falloff (stored as shape) controls strength, with Square applying a uniform amount. Odd grid rows are 1, 3, 5… and keep their original indices through partial grids. In Wire, only the Range selected in the stack highlights its affected elements, using a stable five-colour palette.':
    'Selecciona elementos, palabras o líneas de texto, o filas o columnas de una rejilla de Clone para los efectos anidados. Select: All, Even, Odd o An+B al estilo CSS (empezando en uno). Start/End/Offset limitan la selección; Falloff (guardado como shape) controla la fuerza, y Square aplica una cantidad uniforme. Las filas impares de la rejilla son la 1, 3, 5… y conservan sus índices originales en rejillas parciales. En Wire, solo el Range seleccionado en la pila resalta sus elementos, con una paleta estable de cinco colores.',
  // field
  'Field selector: the nested effects act more or less on each element depending on where it is relative to a shape (ellipse, plane or box). Circle and Box take Width and Height; Linear fades over Distance. Contain decides when an element counts as inside: its centre, all of it (full) or any part of it (partial). Move the field to sweep the drawing; Softness is how much of the edge is a transition. In an Effector node the field is one place in the scene (fractions of the document) for all its targets.':
    'Selector por campo: los efectos anidados actúan más o menos en cada elemento según dónde esté respecto a una forma (elipse, plano o caja). Circle y Box usan Width y Height; Linear se desvanece a lo largo de Distance. Contain decide cuándo un elemento cuenta como dentro: su centro, entero (full) o cualquier parte (partial). Mueve el campo para barrer el dibujo; Softness es cuánto del borde es transición. En un nodo Effector, el campo es un lugar de la escena (fracciones del documento) para todos sus destinos.',
  // particles
  'Seeded particle generator that uses the complete source object as its particle: geometry, colours and relative proportions are preserved. Burst or continuous stream, lifetime and fade, emitter area, direction, spread, velocity and spin. Free motion supports gravity, drag, constant wind drift, smooth seeded turbulence and spiral motion. Lifetimes can vary; particles can fade in, fade out and change size over their life, and Stretch by speed lengthens each one along its direction of travel (motion streaks for sparks, rain or fireworks). Explicit birth rate, prewarm and reference size separate emission and motion scale from the source artwork. Burst impulse mode passes velocity and spin to a following Gravity or to the Physics of an enclosing group. Time follows scene.time unless it is set (a number, keys or a formula). Up to 512 live particles, reduced for very complex sources.':
    'Generador de partículas con semilla que usa el objeto de origen completo como partícula: se conservan su geometría, sus colores y sus proporciones. Ráfaga o flujo continuo, vida y desvanecimiento, área del emisor, dirección, dispersión, velocidad y giro. El movimiento libre admite gravedad, resistencia, viento constante, turbulencia suave con semilla y movimiento en espiral. La vida puede variar; las partículas pueden aparecer y desaparecer gradualmente y cambiar de tamaño a lo largo de su vida, y Stretch by speed alarga cada una en su dirección de avance (estelas para chispas, lluvia o fuegos artificiales). La tasa de nacimiento, el precalentamiento y el tamaño de referencia explícitos separan la escala de emisión y de movimiento del dibujo de origen. El modo de impulso de ráfaga pasa la velocidad y el giro a un Gravity posterior o al Physics de un grupo contenedor. Time sigue a scene.time salvo que se fije (un número, claves o una fórmula). Hasta 512 partículas vivas, menos con orígenes muy complejos.',
  // gravity
  'Drops each element onto a virtual floor, rigid by default or elastic when it carries Soft Body material, inheriting velocity and spin from Explosion or Rigid Body. Enable Collisions for piece-to-piece contacts; select Solids to collide with other objects as fixed obstacles. If the input exceeds 512 paths, Gravity combines it into one simplified body and disables body and Solid collisions, reporting a diagnostic so playback stays responsive. Friction and Bounce apply to all contacts. Only the exterior of each shape collides (letter counters and holes are solid), while gaps between disconnected filled shapes stay open. For hollow obstacles that contain bodies, use Physics. Targets use their current-frame geometry throughout the replay, not their past movement. Floor rotation is measured from the scene horizon, independently of the object or parent rotation. Crosshatch lines collide with Solids and the Floor consistently: Merge on keeps one body across colours; off, each stroke is independent. Initially crossed line pairs start colliding only after separating, so playback does not eject the screen at startup. Other ordinary open paths retain floor-only dynamics. Cached deterministic simulation, up to 3600 seconds. Inside a group with Physics it does not simulate on its own: it adds its pull and floor to that Physics, for the bodies it is on.':
    'Deja caer cada elemento sobre un suelo virtual, rígido por defecto o elástico si lleva material Soft Body, heredando la velocidad y el giro de Explosion o Rigid Body. Activa Collisions para los contactos entre piezas; elige Solids para chocar con otros objetos como obstáculos fijos. Si la entrada pasa de 512 trazados, Gravity la combina en un único cuerpo simplificado y desactiva las colisiones entre cuerpos y con Solids, con un aviso de diagnóstico para que la reproducción siga fluida. Friction y Bounce se aplican a todos los contactos. Solo choca el exterior de cada forma (los huecos de las letras y los agujeros son macizos), mientras que los espacios entre formas rellenas separadas siguen abiertos. Para obstáculos huecos que contengan cuerpos, usa Physics. Los destinos usan su geometría del fotograma actual durante toda la repetición, no su movimiento pasado. La rotación del suelo se mide desde el horizonte de la escena, sin depender de la rotación del objeto o de su padre. Las líneas de Crosshatch chocan de forma coherente con Solids y con el suelo: con Merge activado se mantiene un cuerpo para todos los colores; desactivado, cada trazo es independiente. Los pares de líneas que empiezan cruzados solo empiezan a chocar tras separarse, para que la reproducción no expulse la trama al inicio. Los demás trazados abiertos normales solo chocan con el suelo. Simulación determinista en caché, hasta 3600 segundos. Dentro de un grupo con Physics no simula por su cuenta: añade su atracción y su suelo a ese Physics, para los cuerpos en los que está.',
  // softbody
  'Elastic material for open fibres and closed bodies. Stiffness, Bending, Keep area, Damping and Recovery define deformation and recovery; fibres may be free or pinned. Body model defaults to Outline; Beam adds a flexible internal spine and cross-sections that carry a broad bend through a closed, elongated body, then recover toward its rigid rest shape as impacts settle. Recovery controls how strongly it returns once internal motion dies down; Bounce and floor contacts still come from Gravity or Physics. Changes no geometry by itself. Apply to chooses both, fibres only or closed bodies only.':
    'Material elástico para fibras abiertas y cuerpos cerrados. Stiffness, Bending, Keep area, Damping y Recovery definen la deformación y la recuperación; las fibras pueden ir libres o sujetas. Body model es Outline por defecto; Beam añade una columna interna flexible y secciones que transmiten una curvatura amplia a lo largo de un cuerpo cerrado y alargado, y luego recupera su forma rígida de reposo cuando los impactos se asientan. Recovery controla con qué fuerza vuelve cuando el movimiento interno se calma; el rebote y los contactos con el suelo siguen viniendo de Gravity o Physics. No cambia la geometría por sí solo. Apply to elige ambos, solo fibras o solo cuerpos cerrados.',
  // physics
  'A 2D dynamics simulation for the children of a group: each element is a rigid body, or elastic when it carries Soft Body. Collisions between bodies are optional; Solids are fixed obstacles from other objects (holes are kept, so a hollow shape can contain bodies). Acceleration is a constant force for all; Air drag slows moving bodies down; Friction and Bounce apply to every contact. Each child\'s start (velocity, spin, immovable, attraction) comes from Rigid Body, and a Gravity on a child adds its own pull and floor. A live world: it steps forward from the previous frame, so a body that appears (a Mouse Instance click in the group, a child that starts to exist, an Explosion\'s pieces) joins the running simulation at that moment, and seeking back restores a snapshot; editing the scene restarts it. In Play, the pointer can act on the body under it: Click push pushes it away from the click, Double-click burst breaks it into pieces that fly out from its centre, and Drag & throw grabs it with a spring and throws it on release; Hover push (a radius in px) lets the pointer sweep the bodies it passes near without clicking, carrying them along and aside (rigid bodies; turn Body collisions off for thousands of pieces). The document\'s edges can be walls for every Physics (Document → Walls). Network links follow the bodies they join. Up to 3600 seconds.':
    'Una simulación dinámica 2D para los hijos de un grupo: cada elemento es un cuerpo rígido, o elástico si lleva Soft Body. Las colisiones entre cuerpos son opcionales; Solids son obstáculos fijos de otros objetos (se conservan los agujeros, así una forma hueca puede contener cuerpos). Acceleration es una fuerza constante para todos; Air drag frena los cuerpos en movimiento; Friction y Bounce se aplican a todos los contactos. El arranque de cada hijo (velocidad, giro, inmóvil, atracción) sale de Rigid Body, y un Gravity en un hijo añade su propia atracción y su suelo. Es un mundo vivo: avanza desde el fotograma anterior, así un cuerpo que aparece (un clic de Mouse Instance en el grupo, un hijo que empieza a existir, las piezas de una Explosion) se une a la simulación en marcha en ese momento, e ir hacia atrás restaura una instantánea; editar la escena la reinicia. En Play, el puntero puede actuar sobre el cuerpo que tiene debajo: Click push lo empuja lejos del clic, Double-click burst lo rompe en piezas que salen despedidas desde su centro y Drag & throw lo agarra con un muelle y lo lanza al soltar; Hover push (un radio en px) deja que el puntero barra los cuerpos que tiene cerca sin hacer clic, llevándoselos y apartándolos (cuerpos rígidos; desactiva Body collisions para miles de piezas). Los bordes del documento pueden ser paredes para todos los Physics (Documento → Paredes). Los enlaces de Network siguen a los cuerpos que unen. Hasta 3600 segundos.',
  // rigidbody
  'How a child of a Physics group (or of an object with Gravity) starts: initial Velocity and Spin, Immovable to make it a fixed collider, and the Mass center (Auto uses the geometry\'s; Custom moves it with a handle, changing how the body turns and rests). Attractor pulls the other rigid bodies towards the nearest point of its solid geometry with an inverse-square field (holes kept): Strength and Range are relative to the largest body, moving or fixed; the reaction moves the attractor unless it is Immovable. Absorption reduces bounce and damps motion on impact while keeping the approach speed, and Settle zeroes residual motion below a speed, so bodies rebound a few times and come to rest.':
    'Cómo arranca un hijo de un grupo con Physics (o de un objeto con Gravity): Velocity y Spin iniciales, Immovable para convertirlo en un obstáculo fijo y el centro de masas (Auto usa el de la geometría; Custom lo mueve con un tirador, cambiando cómo gira y reposa el cuerpo). Attractor atrae a los demás cuerpos rígidos hacia el punto más cercano de su geometría sólida con un campo de cuadrado inverso (se conservan los agujeros): Strength y Range son relativos al cuerpo más grande, móvil o fijo; la reacción mueve el atractor salvo que sea Immovable. Absorption reduce el rebote y amortigua el movimiento en el impacto manteniendo la velocidad de llegada, y Settle anula el movimiento residual por debajo de una velocidad, así los cuerpos rebotan unas pocas veces y se quedan quietos.',
  // explosion
  'Each element (a piece of Damage or Crack, a Mosaic tile, a Clone copy, a letter…) flies away from a centre: it moves out, spins and shrinks a little, each in its own way. `amount` from 0 to 1 plays the explosion. Motion: impulse launches the pieces through a following Gravity or an enclosing Physics group, preserving velocity and spin; offset keeps the direct displacement mode.':
    'Cada elemento (una pieza de Damage o Crack, una tesela de Mosaic, una copia de Clone, una letra…) sale despedido desde un centro: se aleja, gira y encoge un poco, cada uno a su manera. `amount` de 0 a 1 reproduce la explosión. Motion: impulse lanza las piezas a través de un Gravity posterior o de un grupo con Physics que las contiene, conservando su velocidad y su giro; offset mantiene el modo de desplazamiento directo.',
  // color
  'Assign or vary colour per element: `solid` assigns the selected colour to fill, stroke or both; `shift` rotates the hue and adjusts saturation and lightness; `gradient` spreads a gradient across the elements; `random` varies them at random; `palette` picks one exact colour from an editable list for each element, including each Clone copy. Copies emitted by one Mouse Instance input event share a palette choice.':
    'Asigna o varía el color por elemento: `solid` asigna el color elegido al relleno, al contorno o a ambos; `shift` gira el tono y ajusta la saturación y la luminosidad; `gradient` reparte un degradado entre los elementos; `random` los varía al azar; `palette` elige un color exacto de una lista editable para cada elemento, también para cada copia de Clone. Las copias emitidas por un mismo evento de un Mouse Instance comparten la elección de la paleta.',
  // tint
  'Pushes the colour towards a target colour. Inside Step the amount grows copy by copy (white lightens, black darkens).':
    'Lleva el color hacia un color de destino. Dentro de Step la cantidad crece copia a copia (el blanco aclara y el negro oscurece).',
  // paint
  'Fill and stroke: lays a colour over the fill (amount 1 replaces it) and adds or changes the stroke: width, opacity, joins, caps, dashes and paint order.':
    'Relleno y contorno: pone un color sobre el relleno (amount 1 lo sustituye) y añade o cambia el contorno: grosor, opacidad, uniones, extremos, discontinuos y orden de pintado.',
  // gradient
  'A gradient on the fill or the stroke of each shape: linear (with an angle) or radial (centre, radius and focus), with an optional middle colour (`via`). Relative to each shape\'s box, so it follows the shape.':
    'Un degradado en el relleno o en el contorno de cada forma: lineal (con un ángulo) o radial (centro, radio y foco), con un color intermedio opcional (`via`). Es relativo a la caja de cada forma, así que la sigue.',
  // imagefill
  'Fills each shape from a raster image object in the scene. Hide source is on by default: the image stays available as a fill but is not drawn or treated as a separate physics body. Turn it off to show the source object. Cover preserves proportions and crops, Contain preserves proportions and leaves the fill colour behind, and Stretch fills the whole shape. Uses the original stack bounds as one shared image frame; Crack shards, Clone copies and Voronoi cells preserve that image material through generation, and it moves with Gravity.':
    'Rellena cada forma con un objeto de imagen raster de la escena. Hide source está activado por defecto: la imagen sigue disponible como relleno pero no se dibuja ni cuenta como un cuerpo físico aparte. Desactívalo para ver el objeto de origen. Cover mantiene las proporciones y recorta, Contain mantiene las proporciones y deja ver el color de relleno detrás, y Stretch llena toda la forma. Usa los límites originales de la pila como un único marco de imagen común; los fragmentos de Crack, las copias de Clone y las celdas de Voronoi conservan ese material de imagen al generarse, y se mueve con Gravity.',
  // feather
  'Softens a solid fill with a radial fade and slightly expands the shape to preserve its opaque centre. Uses a native SVG gradient instead of a raster blur filter, so it is lighter for many small copies.':
    'Suaviza un relleno sólido con un desvanecimiento radial y amplía un poco la forma para conservar su centro opaco. Usa un degradado SVG nativo en vez de un filtro de desenfoque raster, así pesa menos con muchas copias pequeñas.',
  // mask
  'Native SVG mask: the object only shows where another object lets it (`source`). `shape`: inside the mask\'s shape (`invert`: outside). `luminance`: the mask\'s colours decide (white shows, black hides; a gradient gives soft fades). Whole elements discards copies crossing the boundary instead of clipping them (shape mode). The mask can be hidden and still works.':
    'Máscara SVG nativa: el objeto solo se ve donde otro objeto lo deja (`source`). `shape`: dentro de la forma de la máscara (`invert`: fuera). `luminance`: deciden los colores de la máscara (el blanco muestra, el negro oculta; un degradado da transiciones suaves). Whole elements descarta las copias que cruzan el borde en vez de recortarlas (modo shape). La máscara puede estar oculta y sigue funcionando.',
  // opacity
  'Makes the drawing transparent. With Range or Field, letters or pieces that appear or fade away.':
    'Hace transparente el dibujo. Con Range o Field, letras o piezas que aparecen o se desvanecen.',
  // shadow
  'Drop shadow: a blurred, shifted copy behind the drawing, in one colour.':
    'Sombra paralela: una copia desenfocada y desplazada detrás del dibujo, de un solo color.',
  // blur
  'Blur in both directions or only one (motion blur), on the whole drawing or only in an area.':
    'Desenfoque en las dos direcciones o solo en una (desenfoque de movimiento), en todo el dibujo o solo en una zona.',
  // glow
  'A coloured halo around the drawing, behind it.':
    'Un halo de color alrededor del dibujo, detrás de él.',
  // grain
  'Fine noise over the drawing (only inside it), like film or print grain.':
    'Un ruido fino sobre el dibujo (solo dentro de él), como el grano de la película o de la impresión.',
  // displace
  'The edges tremble or ripple with organic noise. Animate Amount or the seed.':
    'Los bordes tiemblan u ondulan con un ruido orgánico. Anima Amount o la semilla.',
  // bevel
  'Relief: light and shade on the edges, as if the drawing had volume. The light comes from `angle` at `elevation`; `depth` is the bevel width, `height` how much it stands out, `shine` the highlight.':
    'Relieve: luz y sombra en los bordes, como si el dibujo tuviera volumen. La luz llega desde `angle` a `elevation`; `depth` es el ancho del bisel, `height` cuánto sobresale y `shine` el brillo.',
  // thicken
  'Makes the drawing thicker (or thinner with a negative amount), or adds a coloured outline around it like a sticker (`outline`). Works on whatever is painted: text, strokes, anything.':
    'Engrosa el dibujo (o lo adelgaza con una cantidad negativa), o le añade un contorno de color alrededor como una pegatina (`outline`). Funciona con todo lo que esté pintado: texto, trazos, lo que sea.',
  // tone
  'Tone: posterize (few levels per channel, like a poster), duotone (shadows in one colour and lights in another) or invert the colours. On the whole drawing or only in an area.':
    'Tono: posterizar (pocos niveles por canal, como un póster), duotono (las sombras de un color y las luces de otro) o invertir los colores. En todo el dibujo o solo en una zona.',
  // path
  'An editable source path with open or closed cubic Bézier contours. Anchors have independent, smooth or symmetric handles. Coordinates stay in local pixels, so moving points preserves the source origin and the procedural effect stack.':
    'Un trazado de origen editable con contornos Bézier cúbicos abiertos o cerrados. Las anclas tienen tiradores independientes, suaves o simétricos. Las coordenadas se quedan en píxeles locales, así mover puntos conserva el origen y la pila de efectos procedurales.',
  // rectangle
  'A rectangle, with optional rounded corners. Each radius is capped at half the shorter side of the rectangle, then adjacent corners are scaled together if needed to fit.':
    'Un rectángulo, con esquinas redondeadas opcionales. Cada radio se limita a la mitad del lado más corto del rectángulo y, si hace falta, las esquinas contiguas se escalan juntas para que quepan.',
  // ellipse
  'An ellipse (a circle when width and height match).':
    'Una elipse (un círculo cuando el ancho y el alto coinciden).',
  // donut
  'A ring: a circle of radius Outer with a round hole of radius Inner, both exact curves. Inner 0 (or not smaller than Outer) leaves a plain circle. Stretch the object for an elliptical ring.':
    'Un anillo: un círculo de radio Outer con un agujero redondo de radio Inner, ambos curvas exactas. Inner 0 (o no menor que Outer) deja un círculo normal. Estira el objeto para un anillo elíptico.',
  // polygon
  'A regular polygon with any number of sides.':
    'Un polígono regular con cualquier número de lados.',
  // star
  'A star with any number of points and an inner radius (2 points make a needle or a diamond).':
    'Una estrella con cualquier número de puntas y un radio interior (2 puntas forman una aguja o un rombo).',
  // line
  'A straight line, by length and angle. Stroke only by default.':
    'Una línea recta, por longitud y ángulo. Solo contorno por defecto.',
  // spiral
  'An Archimedean spiral, by radius and number of turns. Stroke only by default.':
    'Una espiral de Arquímedes, por radio y número de vueltas. Solo contorno por defecto.',
  // randomwave
  'An autonomous synthesizer-style wave source with random, sine, square, triangle and sawtooth modes. Cycles, speed, phase and amplitude shape the signal; it needs no input shape.':
    'Una fuente de onda autónoma al estilo de un sintetizador, con modos aleatorio, seno, cuadrada, triángulo y diente de sierra. Cycles, speed, phase y amplitude dan forma a la señal; no necesita ninguna forma de entrada.',
  // randombars
  'An autonomous seeded signal drawn as vertical bars extending from a horizontal centreline. Bar heights and directions refresh at the selected update rate.':
    'Una señal autónoma con semilla dibujada como barras verticales que salen de una línea central horizontal. La altura y la dirección de las barras se renuevan al ritmo de actualización elegido.',
  // text
  'Text turned into outlines, one piece per letter (so Step, Stagger and Range can treat letters, words and lines separately). Uses the registered fonts.':
    'Texto convertido en contornos, una pieza por letra (así Step, Stagger y Range pueden tratar letras, palabras y líneas por separado). Usa las fuentes registradas.',
  // arrow
  'A continuous arrow outline with independent Start head and End head selectors: none, triangular, V, square or round. Head / length sets the head length relative to the total; Head / body width controls its width. V depth controls the chevron notch. Numeric proportions can be animated.':
    'El contorno continuo de una flecha con selectores independientes para la punta de inicio y la de final: ninguna, triangular, en V, cuadrada o redonda. Head / length fija la longitud de la punta respecto al total; Head / body width controla su ancho. V depth controla la muesca del chevrón. Las proporciones numéricas se pueden animar.',
  // cross
  'A filled plus sign: Size controls the overall extent and Width the thickness of its arms, clamped to Size. Rotate the object 45 degrees for an X.':
    'Un signo más relleno: Size controla el tamaño total y Width el grosor de sus brazos, limitado a Size. Gira el objeto 45 grados para una X.',
  // pawn
  'A chess pawn: svertik\'s test shape, with curves and straight parts.':
    'Un peón de ajedrez: la forma de prueba de svertik, con curvas y partes rectas.',
};
